// Application with PostgreSQL health check endpoint
const express = require('express');
const { Client } = require('pg');

const app = express();

// Parse DATABASE_URL from environment or use default
const databaseUrl = process.env.DATABASE_URL || 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production';

// Create PostgreSQL client
const dbClient = new Client({
  connectionString: databaseUrl,
  connectionTimeoutMillis: 5000, // 5 second timeout for health checks
});

// Health check endpoint with DB connectivity check
app.get('/healthz', async (req, res) => {
  try {
    // Try to connect to PostgreSQL if not already connected
    if (dbClient._ending || dbClient._connecting) {
      // Client is in a bad state, create a new one
      const tempClient = new Client({
        connectionString: databaseUrl,
        connectionTimeoutMillis: 5000,
      });
      await tempClient.connect();
      await tempClient.end();
    } else {
      // Use existing client or create new connection
      await dbClient.connect();
    }

    // Simple query to verify DB is responsive
    const result = await dbClient.query('SELECT 1 as health_check');

    if (result.rows[0].health_check === 1) {
      res.status(200).json({ db: 'ok' });
    } else {
      res.status(503).json({ db: 'error', message: 'Database health check failed' });
    }
  } catch (error) {
    console.error('Health check failed:', error.message);
    res.status(503).json({ 
      db: 'error', 
      message: 'Database connection failed',
      error: error.message 
    });
  } finally {
    // End the connection to avoid connection pool exhaustion
    try {
      if (!dbClient._ending) {
        await dbClient.end();
      }
    } catch (endError) {
      // Ignore end errors
    }
  }
});

// Keep the existing health endpoint for backward compatibility
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Test DB connection on startup
dbClient.connect()
  .then(() => {
    console.log('✅ Database connection established');
    return dbClient.end();
  })
  .catch(err => {
    console.error('❌ Database connection failed:', err.message);
    console.log('⚠️  Service will start, but /healthz may return 503');
  });

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;

