// CI secret-sync script
const fs = require('fs');
const http = require('http');

// Read .env.test file
try {
  const envContent = fs.readFileSync('.env.test', 'utf8');

  // Parse the .env file into key-value pairs
  const envVars = {};
  envContent.split('\n').forEach(line => {
    line = line.trim();
    if (line && !line.startsWith('#')) {
      const [key, ...valueParts] = line.split('=');
      if (key) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  console.log('Read environment variables from .env.test:', Object.keys(envVars));

  // Prepare the POST request
  const postData = JSON.stringify(envVars);

  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/ci-secret-sync',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(postData)
    }
  };

  const req = http.request(options, (res) => {
    console.log(`CI Secret Sync Response Status: ${res.statusCode}`);

    let data = '';
    res.on('data', (chunk) => {
      data += chunk;
    });

    res.on('end', () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        console.log('✅ CI secret sync completed successfully');
        process.exit(0);
      } else {
        console.error('❌ CI secret sync failed with status:', res.statusCode);
        console.error('Response:', data);
        process.exit(1);
      }
    });
  });

  req.on('error', (error) => {
    console.error('CI secret sync request failed:', error.message);
    process.exit(1);
  });

  req.write(postData);
  req.end();

} catch (error) {
  console.error('Error reading .env.test or syncing secrets:', error.message);
  process.exit(1);
}

