// Secret sync script for CI
// This script reads .env.test and POSTs its contents to the CI secret sync endpoint
const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse the .env file content into a JSON object
function parseEnv(content) {
  const result = {};
  const lines = content.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();

    // Skip empty lines and comments
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    const equalsIndex = trimmedLine.indexOf('=');
    if (equalsIndex !== -1) {
      const key = trimmedLine.substring(0, equalsIndex).trim();
      const value = trimmedLine.substring(equalsIndex + 1).trim();
      result[key] = value;
    }
  }

  return result;
}

const secrets = parseEnv(envContent);

// Make the POST request
const options = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/ci-secret-sync',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
  },
};

const req = https.request(options, (res) => {
  console.log(`Secret sync response status: ${res.statusCode}`);

  let data = '';
  res.on('data', (chunk) => {
    data += chunk;
  });

  res.on('end', () => {
    console.log('Secret sync completed successfully');
  });
});

req.on('error', (error) => {
  console.error('Secret sync failed:', error.message);
  process.exit(1);
});

req.write(JSON.stringify(secrets));
req.end();

