const express = require('express');
const { Client } = require('pg');

// Mock implementation for demo purposes
const mockPg = {
  Client: class MockClient {
    constructor(config) {
      this.config = config;
      this.connected = false;
    }

    async connect() {
      // Simulate successful connection
      this.connected = true;
      console.log(`Mock: Connected to ${this.config.connectionString}`);
    }

    async query(sql) {
      console.log(`Mock: Executing query: ${sql}`);
      return { rows: [{ '?column?': 1 }] };
    }

    async end() {
      this.connected = false;
      console.log('Mock: Connection closed');
    }
  }
};

// Simulate different scenarios
async function simulateHealthCheckScenario(scenarioName, shouldFail = false) {
  console.log(`\n=== Scenario: ${scenarioName} ===`);

  const app = express();

  app.get('/healthz', async (req, res) => {
    try {
      // Use mock client instead of real pg for demo
      const ClientClass = shouldFail ? 
        class FailingClient {
          async connect() { throw new Error('Connection refused'); }
        } : mockPg.Client;

      const client = new ClientClass({
        connectionString: 'postgres://mock:5432/db'
      });

      await client.connect();
      await client.query('SELECT 1');
      await client.end();

      res.status(200).json({ db: 'ok' });
    } catch (error) {
      console.error(`Error: ${error.message}`);
      res.status(503).json({ 
        db: 'error', 
        message: 'Database connection failed' 
      });
    }
  });

  // Create a test request
  const req = { method: 'GET', url: '/healthz' };
  const res = {
    statusCode: null,
    body: null,
    status(code) {
