# Real Database Implementation Example

The current implementation simulates database connectivity for demonstration purposes. Here's how to implement real Postgres connectivity:

## 1. Add Postgres Client Dependency

```json
{
  "dependencies": {
    "pg": "^8.11.0"
  }
}
```

## 2. Update `checkDatabaseConnection()` Function

Replace the simulated function with this real implementation:

```javascript
const { Client } = require('pg');

async function checkDatabaseConnection() {
  let client;

  try {
    const databaseUrl = process.env.DATABASE_URL;

    if (!databaseUrl) {
      throw new Error('DATABASE_URL not configured');
    }

    client = new Client({
      connectionString: databaseUrl,
      // Recommended timeouts for health checks
      connectionTimeoutMillis: 5000,
      query_timeout: 3000,
      statement_timeout: 3000
    });

    await client.connect();

    // Simple query to verify database is responsive
    const result = await client.query('SELECT 1 as health_check');

    // Verify we got a valid response
    if (!result.rows || result.rows[0].health_check !== 1) {
      throw new Error('Database query returned unexpected result');
    }

    return { status: 'ok' };

  } catch (error) {
    console.error('Database health check failed:', error.message);
    return { 
      status: 'error', 
      message: error.message,
      code: error.code // PostgreSQL error code if available
    };

  } finally {
    if (client) {
      try {
        await client.end();
      } catch (endError) {
        console.warn('Error closing database connection:', endError.message);
      }
    }
  }
}
```

## 3. Connection Pool for Production

For production use, consider using a connection pool:

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20, // Maximum number of clients in the pool
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

async function checkDatabaseConnection() {
  let client;

  try {
    client = await pool.connect();
    const result = await client.query('SELECT 1 as health_check');

    if (!result.rows || result.rows[0].health_check !== 1) {
      throw new Error('Database health check failed');
    }

    return { status: 'ok' };

  } catch (error) {
    console.error('Database health check failed:', error.message);
    return { status: 'error', message: error.message };

  } finally {
    if (client) {
      client.release();
    }
  }
}
```

## 4. Enhanced Health Check Endpoint

You can extend the health check to include more detailed information:

```javascript
app.get('/healthz', async (req, res) => {
  const healthCheck = {
    status: 'healthy',
    timestamp: new Date().toISOString(),
    checks: {}
  };

  try {
    const dbStatus = await checkDatabaseConnection();
    healthCheck.checks.database = dbStatus;

    if (dbStatus.status === 'ok') {
      healthCheck.checks.database.status = 'healthy';
      res.status(200).json(healthCheck);
    } else {
      healthCheck.status = 'unhealthy';
      healthCheck.checks.database.status = 'unhealthy';
      res.status(503).json(healthCheck);
    }

  } catch (error) {
    healthCheck.status = 'unhealthy';
    healthCheck.checks.database = {
      status: 'unhealthy',
      error: error.message
    };
    res.status(503).json(healthCheck);
  }
});
```

## 5. Kubernetes Configuration

With real database connectivity, your Kubernetes configuration would be:

```yaml
apiVersion: apps/v1
kind: Deployment
metadata:
  name: api-service
spec:
  replicas: 3
  selector:
    matchLabels:
      app: api-service
  template:
    metadata:
      labels:
        app: api-service
    spec:
      containers:
      - name: api
        image: your-api-image:latest
        ports:
        - containerPort: 3000
        env:
        - name: DATABASE_URL
          valueFrom:
            secretKeyRef:
              name: database-secrets
              key: connection-string
        readinessProbe:
          httpGet:
            path: /healthz
            port: 3000
          initialDelaySeconds: 10  # Give time for DB connection
          periodSeconds: 5
          failureThreshold: 3
        livenessProbe:
          httpGet:
            path: /health
            port: 3000
          initialDelaySeconds: 30
          periodSeconds: 10
```

## 6. Testing with Real Database

Create a test script that uses a test database:

```javascript
