const express = require('express');
const { Pool } = require('pg');
require('dotenv').config();

const app = express();

// Create a PostgreSQL connection pool
let pool;

try {
  pool = new Pool({
    connectionString: process.env.DATABASE_URL,
    // Add a timeout for health checks
    connectionTimeoutMillis: 5000,
  });

  // Test the connection on startup
  pool.on('connect', () => {
    console.log('PostgreSQL pool connected');
  });

  pool.on('error', (err) => {
    console.error('Unexpected PostgreSQL pool error:', err);
  });
} catch (error) {
  console.error('Failed to create PostgreSQL pool:', error);
  process.exit(1);
}

// Healthz endpoint with database connectivity check
app.get('/healthz', async (req, res) => {
  try {
    if (!pool) {
      return res.status(503).json({ 
        error: 'Database pool not initialized',
        db: 'error'
      });
    }

    // Try to query the database
    const client = await pool.connect();

    try {
      // Simple query to check database connectivity
      await client.query('SELECT 1 as health_check');

      // Release the client back to the pool
      client.release();

      // Return 200 OK with db status
      return res.status(200).json({ 
        status: 'ok',
        db: 'ok',
        timestamp: new Date().toISOString()
      });
    } catch (queryError) {
      client.release();
      console.error('Database health check query failed:', queryError);
      return res.status(503).json({ 
        error: 'Database query failed',
        db: 'error',
        details: queryError.message
      });
    }
  } catch (connectionError) {
    console.error('Database connection failed:', connectionError);
    return res.status(503).json({ 
      error: 'Database connection failed',
      db: 'error',
      details: connectionError.message
    });
  }
});

// Legacy health endpoint (keep for backward compatibility)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

