#!/usr/bin/env node

const fs = require('fs');

// Read the .env.test file
const envTestPath = '.env.test';

try {
  const envContent = fs.readFileSync(envTestPath, 'utf8');
  console.log('Read .env.test successfully');

  // Parse the .env file content
  const envLines = envContent.split('\n');
  const envVars = {};

  envLines.forEach(line => {
    // Skip empty lines and comments
    if (line.trim() === '' || line.startsWith('#')) {
      return;
    }

    const [key, ...valueParts] = line.split('=');
    if (key && valueParts.length > 0) {
      envVars[key.trim()] = valueParts.join('=').trim();
    }
  });

  console.log('Parsed environment variables:', Object.keys(envVars));

  // Send to CI secret sync endpoint
  const url = 'http://localhost:47301/api/ci-secret-sync';

  // Use fetch or http module to POST the data
  try {
    const https = require('https');
    const http = require('http');

    const data = JSON.stringify(envVars);

    console.log(`Attempting to send secrets to ${url}...`);

    // Determine if we should use http or https
    const isHttps = url.startsWith('https://');
    const transport = isHttps ? https : http;

    const parsedUrl = new URL(url);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || (isHttps ? 443 : 80),
      path: parsedUrl.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data),
      },
    };

    const req = transport.request(options, (res) => {
      console.log(`Status: ${res.statusCode}`);

      let responseData = '';
      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('Secret sync successful:', responseData);
        } else {
          console.error('Secret sync failed:', responseData);
        }
      });
    });

    req.on('error', (error) => {
      console.error('Error sending secrets:', error.message);
      // Continue anyway as this might be expected in some environments
    });

    req.write(data);
    req.end();

  } catch (fetchError) {
    console.error('Failed to send secrets:', fetchError.message);
    console.log('This might be expected if the CI endpoint is not available locally.');
  }

} catch (error) {
  console.error('Error reading .env.test:', error.message);
  process.exit(1);
}

